from itertools import combinations


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bits.get(source, 0)
    limit = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    initial = (source, initial_mask, 0)
    dist = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and (
                coupon_rule == "at_most" or used == limit):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < limit:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_route(coupon_rule, minimum_duration):
    return lambda data: _route(data, coupon_rule, minimum_duration)


def _build_ledger():
    def rounded(numerator, denominator, mode):
        q, r = divmod(numerator, denominator)
        return q + (1 if mode == "half_up" and 2 * r >= denominator else 0)

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}

    return solve


def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        initial_constraints = {name: [tuple(bounds)]
                               for name, bounds in data["roots"].items()}
        best_vector = None
        best = None

        def visit(constraints, chosen, edges):
            nonlocal best_vector, best
            for name, version in chosen.items():
                if any(not low <= version <= high
                       for low, high in constraints.get(name, [])):
                    return
            unresolved = sorted(set(constraints) - set(chosen))
            if not unresolved:
                finished, active = set(), set()

                def acyclic(name):
                    if name in active:
                        return False
                    if name in finished:
                        return True
                    active.add(name)
                    if any(not acyclic(other) for other in edges.get(name, ())):
                        return False
                    active.remove(name)
                    finished.add(name)
                    return True

                if not all(acyclic(name) for name in edges):
                    return
                vector = tuple(chosen.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best = dict(chosen)
                return

            name = unresolved[0]
            ranges = constraints[name]
            rows = sorted(packages.get(name, []),
                          key=lambda row: row["version"], reverse=True)
            for row in rows:
                version = row["version"]
                if any(not low <= version <= high for low, high in ranges):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                next_constraints = {key: list(value)
                                    for key, value in constraints.items()}
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_edges = {key: set(value) for key, value in edges.items()}
                next_edges.setdefault(name, set())
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    next_constraints.setdefault(target, []).append(
                        (dep["min"], dep["max"]))
                    next_edges[name].add(target)
                visit(next_constraints, next_chosen, next_edges)

        visit(initial_constraints, {}, {})
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}

    return solve


def _build_jobs():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(jobs, k):
            ids = [job["id"] for job in subset]
            if blocked.intersection(ids) or not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            active = []
            feasible = True
            for job in ordered:
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > 2:
                    feasible = False
                    break
            if not feasible:
                continue

            selected = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value = value
                best_ids = selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}

    return solve


